declare(strict_types=1);
require __DIR__ . '/../app/bootstrap.php';
require_login();
$u=current_user();
if (($u['role_code']??'')==='CUSTOMER') { http_response_code(403); exit('Forbidden'); }
function h(string $title): void { $u=current_user(); ?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> - MSP ITSM</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/app.css" rel="stylesheet"></head><body><nav class="navbar navbar-dark bg-primary"><div class="container-fluid"><a class="navbar-brand" href="index.php?page=dashboard">MSP ITSM</a><span class="text-white"><?=e($u['full_name'])?> · <a class="text-white" href="index.php?page=logout">Logout</a></span></div></nav><main class="container-fluid p-4"><?php foreach(flashes() as [$t,$m]):?><div class="alert alert-<?=$t?>"><?=e($m)?></div><?php endforeach; ?><h2><?=e($title)?></h2><?php }
function f(): void { ?></main><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html><?php }
$action=(string)get('action','list');
if($action==='save'){ verify_csrf(); $id=(int)post('id',0); $code=strtoupper(trim((string)post('code'))); $name=trim((string)post('name')); $email=trim((string)post('email')); $phone=trim((string)post('phone')); $address=trim((string)post('address')); $status=(string)post('status','ACTIVE'); if(!preg_match('/^[A-Z0-9][A-Z0-9._-]{1,39}$/',$code)) { flash('danger','Customer Code không hợp lệ.'); redirect('customer.php?action=form'.($id?'&id='.$id:'')); } if(mb_strlen($name)<2||mb_strlen($name)>190){flash('danger','Tên Customer phải từ 2 đến 190 ký tự.');redirect('customer.php?action=form'.($id?'&id='.$id:''));} if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL)){flash('danger','Email không hợp lệ.');redirect('customer.php?action=form'.($id?'&id='.$id:''));} if(!in_array($status,['ACTIVE','INACTIVE'],true))$status='ACTIVE'; try { if($id){$s=$db->prepare('UPDATE customers SET name=?,email=?,phone=?,address=?,status=? WHERE id=?');$s->execute([$name,$email?:null,$phone?:null,$address?:null,$status,$id]);audit($db,(int)$u['id'],'UPDATE','CUSTOMER',$id);}else{$s=$db->prepare('INSERT INTO customers(code,name,email,phone,address,status,created_at) VALUES(?,?,?,?,?,?,?)');$s->execute([$code,$name,$email?:null,$phone?:null,$address?:null,$status,now()]);$id=(int)$db->lastInsertId();audit($db,(int)$u['id'],'CREATE','CUSTOMER',$id);}flash('success','Đã lưu Customer.');}catch(PDOException $e){if((int)($e->errorInfo[1]??0)===1062)flash('danger','Customer Code đã tồn tại.');else throw $e;}redirect('customer.php?action=view&id='.$id);}
if($action==='toggle'){verify_csrf();$id=(int)get('id');$s=$db->prepare("UPDATE customers SET status=IF(status='ACTIVE','INACTIVE','ACTIVE') WHERE id=?");$s->execute([$id]);audit($db,(int)$u['id'],'STATUS_CHANGE','CUSTOMER',$id);redirect('customer.php?action=view&id='.$id);}
if($action==='form'){ $id=(int)get('id');$c=['id'=>0,'code'=>'','name'=>'','email'=>'','phone'=>'','address'=>'','status'=>'ACTIVE'];if($id){$s=$db->prepare('SELECT * FROM customers WHERE id=?');$s->execute([$id]);$c=$s->fetch()?:$c;}h($id?'Edit Customer':'Create Customer');?><form method="post" action="customer.php?action=save" class="card shadow-sm border-0 mt-3"><div class="card-body"><?=csrf_field()?><input type="hidden" name="id" value="<?=$c['id']?>"><div class="row g-3"><div class="col-md-4"><label class="form-label">Customer Code *</label><input class="form-control" name="code" required maxlength="40" value="<?=e($c['code'])?>" <?=$id?'readonly':''?>></div><div class="col-md-8"><label class="form-label">Customer Name *</label><input class="form-control" name="name" required maxlength="190" value="<?=e($c['name'])?>"></div><div class="col-md-4"><label class="form-label">Email</label><input type="email" class="form-control" name="email" value="<?=e($c['email']??'')?>"></div><div class="col-md-4"><label class="form-label">Phone</label><input class="form-control" name="phone" value="<?=e($c['phone']??'')?>"></div><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="status"><option value="ACTIVE" <?=$c['status']==='ACTIVE'?'selected':''?>>ACTIVE</option><option value="INACTIVE" <?=$c['status']==='INACTIVE'?'selected':''?>>INACTIVE</option></select></div><div class="col-12"><label class="form-label">Address</label><input class="form-control" name="address" value="<?=e($c['address']??'')?>"></div></div></div><div class="card-footer bg-white"><button class="btn btn-primary">Save Customer</button> <a class="btn btn-outline-secondary" href="customer.php">Cancel</a></div></form><?php f();exit;}
if($action==='view'){ $id=(int)get('id');$s=$db->prepare('SELECT * FROM customers WHERE id=?');$s->execute([$id]);$c=$s->fetch();if(!$c){http_response_code(404);exit('Customer not found');}$s=$db->prepare('SELECT * FROM customer_contacts WHERE customer_id=? ORDER BY is_primary DESC,full_name');$s->execute([$id]);$contacts=$s->fetchAll();$s=$db->prepare('SELECT COUNT(*) FROM contracts WHERE customer_id=?');$s->execute([$id]);$contracts=(int)$s->fetchColumn();$s=$db->prepare("SELECT COUNT(*) FROM tickets WHERE customer_id=? AND status<>'CLOSED'");$s->execute([$id]);$tickets=(int)$s->fetchColumn();h('Customer · '.$c['name']);?><div class="d-flex justify-content-between mt-3 mb-4"><div><div class="text-muted"><?=e($c['code'])?></div><h3><?=e($c['name'])?></h3></div><div><a class="btn btn-outline-primary" href="customer.php?action=form&id=<?=$id?>">Edit</a> <form class="d-inline" method="post" action="customer.php?action=toggle&id=<?=$id?>"><?=csrf_field()?><button class="btn btn-outline-warning"><?=$c['status']==='ACTIVE'?'Deactivate':'Activate'?></button></form></div></div><div class="row g-3"><div class="col-md-4"><div class="kpi"><span>Status</span><b><?=e($c['status'])?></b></div></div><div class="col-md-4"><div class="kpi"><span>Contracts</span><b><?=$contracts?></b></div></div><div class="col-md-4"><div class="kpi"><span>Open Tickets</span><b><?=$tickets?></b></div></div></div><div class="card shadow-sm border-0 mt-4"><div class="card-header bg-white fw-bold">Contacts</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Primary</th><th>Status</th></tr></thead><tbody><?php foreach($contacts as $ct):?><tr><td><?=e($ct['full_name'])?></td><td><?=e($ct['email'])?></td><td><?=e($ct['phone']??'-')?></td><td><?=$ct['is_primary']?'Yes':'-'?></td><td><?=$ct['is_active']?'ACTIVE':'INACTIVE'?></td></tr><?php endforeach;if(!$contacts):?><tr><td colspan="5" class="text-center text-muted py-4">No contacts</td></tr><?php endif;?></tbody></table></div></div><?php f();exit;}
$q=trim((string)get('q',''));$status=(string)get('status','');$where=[];$params=[];if($q!==''){$where[]='(c.code LIKE ? OR c.name LIKE ? OR c.email LIKE ?)';$like="%$q%";$params=[$like,$like,$like];}if(in_array($status,['ACTIVE','INACTIVE'],true)){$where[]='c.status=?';$params[]=$status;}$sql="SELECT c.*,(SELECT COUNT(*) FROM contracts ct WHERE ct.customer_id=c.id) contract_count,(SELECT COUNT(*) FROM tickets t WHERE t.customer_id=c.id AND t.status<>'CLOSED') open_tickets FROM customers c".($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY c.name';$s=$db->prepare($sql);$s->execute($params);$rows=$s->fetchAll();h('Customer Management');?><div class="d-flex justify-content-between align-items-center mt-3 mb-3"><div class="text-muted">Customer Master · Contacts · Contracts · Tickets</div><a class="btn btn-primary" href="customer.php?action=form">+ New Customer</a></div><form class="row g-2 mb-3"><input type="hidden" name="action" value="list"><div class="col-md-5"><input class="form-control" name="q" placeholder="Code / Name / Email" value="<?=e($q)?>"></div><div class="col-md-3"><select class="form-select" name="status"><option value="">All status</option><option value="ACTIVE" <?=$status==='ACTIVE'?'selected':''?>>ACTIVE</option><option value="INACTIVE" <?=$status==='INACTIVE'?'selected':''?>>INACTIVE</option></select></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Filter</button></div></form><div class="card shadow-sm border-0"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Code</th><th>Customer</th><th>Email</th><th>Status</th><th>Contracts</th><th>Open Tickets</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="customer.php?action=view&id=<?=$r['id']?>"><?=e($r['code'])?></a></td><td><?=e($r['name'])?></td><td><?=e($r['email']??'-')?></td><td><span class="badge text-bg-<?=$r['status']==='ACTIVE'?'success':'secondary'?>"><?=e($r['status'])?></span></td><td><?=$r['contract_count']?></td><td><?=$r['open_tickets']?></td><td><a class="btn btn-sm btn-outline-primary" href="customer.php?action=view&id=<?=$r['id']?>">View</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="text-center text-muted py-4">No customers found</td></tr><?php endif;?></tbody></table></div></div><?php f();